required": true, "options": [{"id": "0", "label": "0 — Nunca ou quase nunca"}, {"id": "1", "label": "1 — Ocasionalmente, efeito leve"}, {"id": "2", "label": "2 — Ocasionalmente, efeito forte"}, {"id": "3", "label": "3 — Frequentemente, efeito leve"}, {"id": "4", "label": "4 — Frequentemente, efeito forte"}]}, {"id": "f467fd52-8bae-4ed1-9f5c-5a2d3f4be4a4", "text": "Vontade de urinar frequente ou urgente", "type": "scale", "required": true, "options": [{"id": "0", "label": "0 — Nunca ou quase nunca"}, {"id": "1", "label": "1 — Ocasionalmente, efeito leve"}, {"id": "2", "label": "2 — Ocasionalmente, efeito forte"}, {"id": "3", "label": "3 — Frequentemente, efeito leve"}, {"id": "4", "label": "4 — Frequentemente, efeito forte"}]}, {"id": "69eb574a-6e9b-4211-8fae-f62507df4f74", "text": "Coceira genital ou corrimento", "type": "scale", "required": true, "options": [{"id": "0", "label": "0 — Nunca ou quase nunca"}, {"id": "1", "label": "1 — Ocasionalmente, efeito leve"}, {"id": "2", "label": "2 — Ocasionalmente, efeito forte"}, {"id": "3", "label": "3 — Frequentemente, efeito leve"}, {"id": "4", "label": "4 — Frequentemente, efeito forte"}]}]'::jsonb
)
on conflict (id) do update set
  nome      = excluded.nome,
  tipo      = excluded.tipo,
  descricao = excluded.descricao,
  ativo     = excluded.ativo,
  perguntas = excluded.perguntas;


-- Verificação: 15 sections e 69 scales.
select
  m.nome,
  m.tipo,
  count(*) filter (where p->>'type' = 'section') as sistemas,
  count(*) filter (where p->>'type' = 'scale')   as sintomas
from public.questionario_modelos m,
     lateral jsonb_array_elements(m.perguntas) p
where m.id = 'b1f0c3a2-7d64-4e58-9a01-2f6c8d5e4b70'
group by m.nome, m.tipo;
